 if x.loaded[dir] {return};x.loaded[dir]=true
 packages:=map[string]map[string][]goTypeDeclaration{}
 for _,file:=range x.filesByDir[dir] {
  content,ok:=x.readContent(file);if !ok {continue}
  parsed,err:=parser.ParseFile(token.NewFileSet(),file,content,parser.SkipObjectResolution)
  if err!=nil {continue} // no identity evidence from malformed source
  declarations:=packages[parsed.Name.Name]
  if declarations==nil {declarations=map[string][]goTypeDeclaration{};packages[parsed.Name.Name]=declarations}
  id:="repo:"+dir+":"+parsed.Name.Name
  if modulePath,ok:=x.modules.importPathFor(dir);ok {id=modulePath}
  scope:=&goTypeScope{imports:map[string]string{},declarations:declarations,packageID:id,index:x}
  x.byFile[file]=scope
  for _,imp:=range parsed.Imports {
   importPath,err:=strconv.Unquote(imp.Path.Value);if err!=nil {continue}
   name:=path.Base(importPath)
   if imp.Name!=nil {name=imp.Name.Name}
   if name=="_" || name=="." {continue} // dot imports need declaration evidence
   if _,exists:=scope.imports[name];exists {scope.imports[name]=""} else {scope.imports[name]=importPath}
  }
  for _,decl:=range parsed.Decls {
   gen,ok:=decl.(*ast.GenDecl);if !ok || gen.Tok!=token.TYPE {continue}
   for _,spec:=range gen.Specs {if typ,ok:=spec.(*ast.TypeSpec);ok {declarations[typ.Name.Name]=append(declarations[typ.Name.Name],goTypeDeclaration{typ,scope})}}
  }
 }
}
func (x *goFileImports) forFile(file string) *goTypeScope {
 if x==nil || x.readContent==nil {return nil}
 x.load(normalizeRepoDir(filepath.Dir(file)))
 return x.byFile[file]
}
func (x *goFileImports) signaturesMatch(want,got SymbolRecord) bool {
 return compareGoSignatures(want.Signature,got.Signature,x.forFile(want.FilePath),x.forFile(got.FilePath))==goTypeMatch
}
func compareGoSignatures(want,got string,a,b *goTypeScope) goTypeComparison {
 left,lok:=goSignatureEvidenceKey(want,a);right,rok:=goSignatureEvidenceKey(got,b)
 if !lok || !rok {return goTypeUnknown}
 if left!=right {return goTypeDifferent}
 return goTypeMatch
}
func goSignatureEvidenceKey(signature string,scope *goTypeScope)(string,bool) {
 normalized,ok:=goNormalizedMethodSignature(signature);if !ok {return "",false}
 expr,err:=parser.ParseExpr("func"+normalized);if err!=nil {return "",false}
 return goEvidenceTypeKey(expr,scope,map[string]bool{},0)
}
func goEvidenceNamedType(name string,scope *goTypeScope,seen map[string]bool,depth int)(string,bool) {
 if scope!=nil {
  if decls:=scope.declarations[name];len(decls)>0 {
   if len(decls)!=1 {return "",false} // build variants are not interchangeable evidence
   decl:=decls[0]
   if decl.spec.TypeParams!=nil {return "",false}
   id:=scope.packageID+"."+name
   if !decl.spec.Assign.IsValid() {return "named("+id+")",true}
   if seen[id] {return "",false};seen[id]=true;defer delete(seen,id)
   return goEvidenceTypeKey(decl.spec.Type,decl.scope,seen,depth+1)
  }
 }
 switch name {
 case "byte":return "uint8",true
 case "rune":return "int32",true
 case "any":return "interface{}",true
 case "bool","string","int","int8","int16","int32","int64","uint","uint8","uint16","uint32","uint64","uintptr","float32","float64","complex64","complex128","error":return name,true
 }
 return "",false
}
func goEvidenceTypeKey(expr ast.Expr,scope *goTypeScope,seen map[string]bool,depth int)(string,bool) {
 if depth>64 {return "",false}
 key:=func(e ast.Expr)(string,bool){return goEvidenceTypeKey(e,scope,seen,depth+1)}
 switch e:=expr.(type) {
 case *ast.Ident:return goEvidenceNamedType(e.Name,scope,seen,depth)
 case *ast.SelectorExpr:
  qualifier,ok:=e.X.(*ast.Ident);if !ok || scope==nil {return "",false}
  importPath:=scope.imports[qualifier.Name];if importPath=="" {return "",false}
  if scope.index!=nil {
   if dir,known:=scope.index.packageDirs[importPath];known {
    scope.index.load(dir)
    var target *goTypeScope
    for _,file:=range scope.index.filesByDir[dir] {
     other:=scope.index.byFile[file]
     if other!=nil && len(other.declarations[e.Sel.Name])>0 {
      if target!=nil && target.declarations[e.Sel.Name][0].scope.packageID!=other.packageID {return "",false}
      target=other
     }
    }
    if target==nil {return "",false}
    return goEvidenceNamedType(e.Sel.Name,target,seen,depth+1)
   }
  }
  return "named("+importPath+"."+e.Sel.Name+")",true
 case *ast.ParenExpr:return key(e.X)
 case *ast.StarExpr:k,ok:=key(e.X);return "*"+k,ok
 case *ast.Ellipsis:k,ok:=key(e.Elt);return "..."+k,ok
 case *ast.ArrayType:
  k,ok:=key(e.Elt);if !ok {return "",false}
  if e.Len==nil {return "[]"+k,true}
  n,ok:=e.Len.(*ast.BasicLit);if !ok || n.Kind!=token.INT {return "",false}
  length,err:=strconv.ParseUint(n.Value,0,64);if err!=nil {return "",false}
  return "["+strconv.FormatUint(length,10)+"]"+k,true
 case *ast.MapType:a,ok:=key(e.Key);b,bok:=key(e.Value);return "map["+a+"]"+b,ok&&bok
 case *ast.ChanType:k,ok:=key(e.Value);return "chan"+strconv.Itoa(int(e.Dir))+"("+k+")",ok
 case *ast.InterfaceType:
  if e.Methods==nil || len(e.Methods.List)==0 {return "interface{}",true}
  return "",false
 case *ast.FuncType:
  if e.TypeParams!=nil {return "",false}
  fields:=func(list *ast.FieldList)(string,bool){
   var keys []string
   if list!=nil {for _,field:=range list.List {
    k,ok:=key(field.Type);if !ok {return "",false}
    count:=len(field.Names);if count==0 {count=1}
    for i:=0;i<count;i++ {keys=append(keys,k)}
   }}
   return strings.Join(keys,","),true
  }
  params,ok:=fields(e.Params);results,rok:=fields(e.Results)
  return "func("+params+")("+results+")",ok&&rok
 }
 return "",false
}
